using Microsoft.Extensions.ML;
using TicketClassifier.Models;
using TicketClassifier.Services;

var builder = WebApplication.CreateBuilder(args);

var dataPath = Path.Combine(builder.Environment.ContentRootPath, "Data", "tickets.csv");
var modelPath = Path.Combine(builder.Environment.ContentRootPath, "Data", "model.zip");

builder.Services.AddSingleton<ModelTrainingService>();
builder.Services.AddPredictionEnginePool<TicketInput, TicketPrediction>()
    .FromFile(modelPath);

var app = builder.Build();

// Train the model at startup and return evaluation metrics
app.MapPost("/api/train", (ModelTrainingService trainer) =>
{
    var report = trainer.TrainAndSaveModel(dataPath, modelPath);
    return Results.Ok(new { message = "Model trained successfully", metrics = report });
});

// Predict the category for a support ticket
app.MapPost("/api/predict", (
    TicketRequest request,
    PredictionEnginePool<TicketInput, TicketPrediction> pool) =>
{
    var input = new TicketInput
    {
        Subject = request.Subject,
        Description = request.Description,
        Priority = request.Priority,
    };

    var prediction = pool.Predict(input);

    var labels = new[] { "Billing", "General", "Technical" };
    var confidence = new Dictionary<string, float>();
    for (var i = 0; i < labels.Length && i < prediction.Score.Length; i++)
    {
        confidence[labels[i]] = prediction.Score[i];
    }

