using Microsoft.ML;
using Microsoft.ML.Data;
using TicketClassifier.Models;

arguments.old_str:
// Train the model at startup so the prediction pool has a model to load
var trainer = app.Services.GetRequiredService<ModelTrainingService>();
var report = trainer.TrainAndSaveModel(dataPath, modelPath);
app.Logger.LogInformation("Startup training complete:\n{Report}", report);

app.MapPost("/api/train", (ModelTrainingService svc) =>
{
    var metrics = svc.TrainAndSaveModel(dataPath, modelPath);
    return Results.Ok(new { message = "Model retrained successfully", metrics });
});

app.MapPost("/api/predict", (
    TicketRequest request,
    PredictionEnginePool<TicketInput, TicketPrediction> pool) =>
{
    var input = new TicketInput
    {
        Subject = request.Subject,
        Description = request.Description,
        Priority = request.Priority,
    };

    var prediction = pool.Predict(input);

    var labels = new[] { "Billing", "General", "Technical" };
    var confidence = new Dictionary<string, float>();
    for (var i = 0; i < labels.Length && i < prediction.Score.Length; i++)
    {
        confidence[labels[i]] = prediction.Score[i];
    }

    return Results.Ok(new TicketResponse
    {
        PredictedCategory = prediction.PredictedCategory,
        Confidence = confidence,
    });
});

